// constructors

    public ActivityTest(ActivityService service)
    {
        this.service = service;
        LOGGER.setUseParentHandlers(false);	// only want to output to the provided LogHandler
    }

// test methods
    @Test
    /**
     * Full Create-Read-Update-Delete of a Activity, through a ActivityTest.
     */
    public void testCRUD() throws Throwable {
    try {
        LOGGER.info( "**********************************************************" );
        LOGGER.info( "Beginning full test on ActivityTest..." );

        testCreate();
        testRead();
        testUpdate();
        testGetAll();
        testDelete();

        LOGGER.info( "Successfully ran a full test on ActivityTest..." );
        LOGGER.info( "**********************************************************" );
        LOGGER.info( "" );
    }
    catch( Throwable e ) {
        throw e;
    }
    finally  {
        if ( handler != null ) {
            handler.flush();
            LOGGER.removeHandler(handler);
        }
    }
}

    /**
     * Tests creating a new Activity.
     *
     * @return    Activity
     */
    public Activity testCreate() throws Throwable {
    Activity entity = null;

    LOGGER.info( "ActivityTest:testCreate()" );
    LOGGER.info( "-- Attempting to create a Activity");

    StringBuilder msg = new StringBuilder( "-- Failed to create a Activity" );

    try {
        entity = service.createActivity( generateNewCommand() );
        assertNotNull( entity, msg.toString() );

        theId = entity.getActivityId();
        assertNotNull( theId, msg.toString() + " Contains a null primary key" );

        LOGGER.info( "-- Successfully created a Activity with primary key" + theId );
    }
    catch (Exception e)  {
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( msg.toString() + entity );

        throw e;
    }
    return entity;
}

    /**
     * Tests reading a Activity.
     *
     * @return    Activity
     */
    public Activity testRead() throws Throwable {
    LOGGER.info( "ActivityTest:testRead()" );
    LOGGER.info( "-- Reading a previously created Activity" );

    Activity entity = null;
    StringBuilder msg = new StringBuilder( "-- Failed to read Activity with primary key" );
    msg.append( theId );

    try {
        entity = service.getActivity( new ActivityFetchOneSummary(theId) );

        assertNotNull( entity,msg.toString() );

        // for use later
        theId = entity.getActivityId();

        LOGGER.info( "-- Successfully found Activity " + entity.toString() );
    }
    catch ( Throwable e ) {
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( msg.toString() + " : " + e );

        throw e;
    }

    return( entity );
}

    /**
     * Tests updating a Activity.
     *
     * @return    Activity
     */
    public Activity testUpdate() throws Throwable {
    LOGGER.info( "ActivityTest:testUpdate()" );
    LOGGER.info( "-- Attempting to update a Activity." );

    StringBuilder msg = new StringBuilder( "Failed to update a Activity : " );
    Activity entity = null;

    try {
        UpdateActivityCommand updateCommand = this.generateUpdateCommand();

        // apply the current id as to update the fields of the current entity
        updateCommand.setActivityId( theId );

        assertNotNull( updateCommand, msg.toString() );

        LOGGER.info( "-- Now updating the created Activity." );

        entity = service.updateActivity( updateCommand );

        assertNotNull( entity, msg.toString()  );

        LOGGER.info( "-- Successfully saved Activity - " + entity.toString() );
    }
    catch ( Throwable e ) {
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( msg.toString() + " : primarykey-" + theId + " : entity-" +  entity + " : " + e );

        throw e;
    }

    return( entity );
}

    /**
     * Tests deleting a Activity.
     */
    public void testDelete() throws Throwable {
    LOGGER.info( "ActivityTest:testDelete()" );
    LOGGER.info( "-- Deleting a previously created Activity." );

    try {
        DeleteActivityCommand deleteCommand = new DeleteActivityCommand( theId );

        service.delete( deleteCommand );

        LOGGER.info( "-- Successfully deleted Activity with primary key " + theId );
    }
    catch ( Throwable e ) {
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( "-- Failed to delete Activity with primary key " + theId );

        throw e;
    }
}

    /**
     * Tests getting all Activitys.
     *
     * @return    Collection
     */
    public List<Activity> testGetAll() throws Throwable {
    LOGGER.info( "ActivityTest:testGetAll() - Retrieving Collection of Activitys:" );

    StringBuilder msg = new StringBuilder( "-- Failed to get all Activity : " );
    List<Activity> collection  = null;

    try {
        // call the static get method on the ActivityService
        collection = service.getAllActivity();

        if ( collection == null || collection.size() == 0 ) {
            LOGGER.warning( unexpectedErrorMsg );
            LOGGER.warning( "-- " + msg.toString() + " Empty collection returned."  );
        }
        else {
            // Now print out the values
            Activity currEntity  = null;
            Iterator<Activity> iter = collection.iterator();

            while( iter.hasNext() ) {
                // Retrieve the entity
                currEntity = iter.next();

                assertNotNull( currEntity,"-- null value object in Collection." );
                assertNotNull( currEntity.getActivityId(), "-- value object in Collection has a null primary key" );

                LOGGER.info( " - " + currEntity.toString() );
            }
        }
    }
    catch ( Throwable e ){
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( msg.toString() );

        throw e;
    }

    return( collection );
}

    public ActivityTest setHandler( Handler handler ) {
    this.handler = handler;
    LOGGER.addHandler(handler);	// assign so the LOGGER can only output results to the Handler
    return this;
}


